    "measurement request",
    "wafer identifier",
    "measurement recipe",
    "equipment availability"
  ],
  "outputs": [
    "measurement result",
    "equipment usage record",
    "request completion notice"
  ],
  "activities": [
    {
      "id": "A1",
      "name": "Confirm measurement request and wafer identifier",
      "actor": "measurement engineer"
    },
    {
      "id": "A2",
      "name": "Select suitable measurement equipment",
      "actor": "measurement engineer"
    },
    {
      "id": "A3",
      "name": "Check equipment availability and reserve slot",
      "actor": "measurement engineer"
    },
    {
      "id": "A4",
